def normalize_phone(s):
    import re
    if not s:
        return None
    # Reject if contains alphabetic characters or disallowed symbols
    for ch in s:
        if ch.isalpha():
            return None
        if ch not in '0123456789 +-()':
            return None
    s = s.strip()
    # Handle country code +82 or 82
    if s.startswith('+82'):
        s = s[3:].lstrip()
        s = '0' + s
    elif s.startswith('82'):
        s = s[2:].lstrip()
        s = '0' + s
    # Keep only digits
    digits = re.sub(r'\D', '', s)
    if len(digits) != 11 or not digits.startswith('010'):
        return None
    return f'{digits[:3]}-{digits[3:7]}-{digits[7:]}'
