        raise ValueError(f"잘못된 지속 시간 형식입니다: {s!r}")
    total = 0
    if m.group(1):
        total += int(m.group(1)[:-2]) * 3600
    if m.group(2):
        total += int(m.group(2)[:-1]) * 60
    if m.group(3):
        total += int(m.group(3)[:-1])
