def parse_csv(text):
    result = []
    if not text:
        return result
    row = []
    field = []
    i = 0
    n = len(text)
    inside = False
    while i < n:
        c = text[i]
        if inside:
            if c == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 1  # skip escaped quote
                else:
                    inside = False
            else:
                field.append(c)
        else:
            if c == '"':
                inside = True
            elif c == ',':
                row.append(''.join(field))
                field = []
            elif c == '\n':
                row.append(''.join(field))
                result.append(row)
                row = []
                field = []
            elif c == '\r':
                if i + 1 < n and text[i + 1] == '\n':
                    i += 1
                row.append(''.join(field))
                result.append(row)
                row = []
                field = []
            else:
                field.append(c)
        i += 1
    if inside:
        raise ValueError("Unclosed quoted field")
    # finalize the last field and row if necessary
    if field or row:
        row.append(''.join(field))
        result.append(row)
    return result
