def evaluate(expr):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/()':
            tokens.append(c)
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            dot_seen = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if dot_seen:
                        break
                    dot_seen = True
                j += 1
            num_text = expr[i:j]
            if num_text == '.':
                raise ValueError("invalid number")
            try:
                tokens.append(float(num_text))
            except ValueError:
                raise ValueError("invalid number")
            i = j
        else:
            raise ValueError("unknown character: %r" % c)
    tokens.append('EOF')

    pos = 0

    def peek():
        return tokens[pos]

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        left = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        left = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            right = parse_factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left = left / right
        return left

    def parse_factor():
        tok = peek()
        if tok == '+':
            advance()
            return parse_factor()
        if tok == '-':
            advance()
            return -parse_factor()
        if tok == '(':
            advance()
            val = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return val
        if isinstance(tok, float):
            advance()
            return tok
        raise ValueError("unexpected token: %r" % tok)

    result = parse_expr()
    if peek() != 'EOF':
        raise ValueError("unexpected token: %r" % peek())
    return float(result)
