def evaluate(expr: str) -> float:
    """
    Evaluate a mathematical expression containing +, -, *, /, parentheses,
    unary minus, and floating‑point numbers.  Returns a float.
    Raises ZeroDivisionError for division by zero and ValueError for any
    syntactic problem.
    """
    # ---------- tokenizer ----------
    import re

    _num_pat = re.compile(r'\d+(\.\d*)?|\.\d+')
    _ops = set('+-*/()')
    _whitespace = set(' \t\r\n')

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in _whitespace:
            i += 1
            continue
        if ch in _ops:
            tokens.append(ch)
            i += 1
        elif ch.isdigit() or ch == '.':
            m = _num_pat.match(expr, i)
            if not m:
                raise ValueError("invalid number")
            tokens.append(m.group())
            i = m.end()
        else:
            raise ValueError(f"invalid character '{ch}'")
    if not tokens:
        raise ValueError("empty expression")

    # ---------- parser ----------
    class Parser:
        def __init__(self, toks):
            self.toks = toks
            self.pos = 0

        def peek(self):
            return self.toks[self.pos] if self.pos < len(self.toks) else None

        def consume(self, expected=None):
            cur = self.peek()
            if cur is None:
                raise ValueError("unexpected end of expression")
            if expected is not None and cur != expected:
                raise ValueError(f"expected '{expected}'")
            self.pos += 1
            return cur

        # expr := term ((+|-) term)*
        def parse_expr(self):
            val = self.parse_term()
            while True:
                op = self.peek()
                if op == '+' or op == '-':
                    self.consume()
                    right = self.parse_term()
                    if op == '+':
                        val = val + right
                    else:
                        val = val - right
                else:
                    break
            return val

        # term := factor ((*|/) factor)*
        def parse_term(self):
            val = self.parse_factor()
            while True:
                op = self.peek()
                if op == '*' or op == '/':
                    self.consume()
                    right = self.parse_factor()
                    if op == '*':
                        val = val * right
                    else:
                        if right == 0.0:
                            raise ZeroDivisionError("division by zero")
                        val = val / right
                else:
                    break
            return val

        # factor := (+|-) factor | number | '(' expr ')'
        def parse_factor(self):
            tok = self.peek()
            if tok == '+' or tok == '-':
                self.consume()
                val = self.parse_factor()
                return +val if tok == '+' else -val
            if tok == '(':
                self.consume('(')
                val = self.parse_expr()
                if self.peek() != ')':
                    raise ValueError("missing closing parenthesis")
                self.consume(')')
                return val
            # number
            if tok is None:
                raise ValueError("unexpected end of expression")
            if re.fullmatch(r'\d+(\.\d*)?|\.\d+', tok):
                self.consume()
                return float(tok)
            raise ValueError(f"unexpected token '{tok}'")

    parser = Parser(tokens)
    result = parser.parse_expr()
    if parser.peek() is not None:
        raise ValueError("extra characters after valid expression")
    return float(result)
