def evaluate(expr: str) -> float:
    s = expr
    n = len(s)
    i = 0

    def skip_ws():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip_ws()
        return s[i] if i < n else ''

    def consume(ch: str = None):
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("unexpected end of input")
        cur = s[i]
        if ch is not None and cur != ch:
            raise ValueError(f"expected '{ch}' but got '{cur}'")
        i += 1
        return cur

    def parse_number() -> float:
        nonlocal i
        skip_ws()
        start = i
        has_digit = False
        if i < n and s[i] == '.':
            i += 1
            while i < n and s[i].isdigit():
                i += 1
                has_digit = True
            if not has_digit:
                raise ValueError("invalid number format")
        else:
            while i < n and s[i].isdigit():
                i += 1
                has_digit = True
            if i < n and s[i] == '.':
                i += 1
                while i < n and s[i].isdigit():
                    i += 1
                    has_digit = True
        if not has_digit:
            raise ValueError("expected number")
        try:
            return float(s[start:i])
        except ValueError:
            raise ValueError("invalid number")

    def parse_factor() -> float:
        skip_ws()
        ch = peek()
        if ch == '+':
            consume('+')
            return parse_factor()
        if ch == '-':
            consume('-')
            return -parse_factor()
        if ch == '(':
            consume('(')
            val = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            consume(')')
            return val
        if ch.isdigit() or ch == '.':
            return parse_number()
        raise ValueError(f"unexpected character '{ch}'")

    def parse_term() -> float:
        left = parse_factor()
        while True:
            skip_ws()
            ch = peek()
            if ch == '*':
                consume('*')
                right = parse_factor()
                left = left * right
            elif ch == '/':
                consume('/')
                right = parse_factor()
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left = left / right
            else:
                break
        return left

    def parse_expr() -> float:
        left = parse_term()
        while True:
            skip_ws()
            ch = peek()
            if ch == '+':
                consume('+')
                right = parse_term()
                left = left + right
            elif ch == '-':
                consume('-')
                right = parse_term()
                left = left - right
            else:
                break
        return left

    skip_ws()
    if i >= n:
        raise ValueError("empty expression")
    result = parse_expr()
    skip_ws()
    if i != n:
        raise ValueError("trailing characters")
    return float(result)
