import re

def parse_duration(s: str) -> int:
    if not s or s.strip() == "":
        raise ValueError("")
    cleaned = re.sub(r'\d+(시간|분|초)', '', s)
    cleaned = cleaned.replace(' ', '')
    if cleaned != "":
        raise ValueError("")
    pairs = re.findall(r'(\d+)(시간|분|초)', s)
    if not pairs:
        raise ValueError("")
    order = {'시간': 0, '분': 1, '초': 2}
    seen_index = -1
    used_units = set()
    total = 0
    for num_str, unit in pairs:
        num = int(num_str)
        if unit not in order:
            raise ValueError("")
        idx = order[unit]
        if idx < seen_index:
            raise ValueError("")
        if unit in used_units:
            raise ValueError("")
        used_units.add(unit)
        seen_index = idx
        if unit == '시간':
            total += num * 3600
        elif unit == '분':
            total += num * 60
        else:
            total += num
    return total
