            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                if expr[i] == '.':
                    if dot_seen:
                        raise ValueError("Invalid number format")
                    dot_seen = True
                i += 1
            num_str = expr[start:i]
            try:
                val = float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number: {num_str}")
            tokens.append(('NUM', val))
            continue

        # Operator and parenthesis parsing
        if c in '+-*/()':
            # Detect unary minus
            if c == '-' and (len(tokens) == 0 or tokens[-1][0] in ('OP', 'LPAREN')):
                tokens.append(('OP', 'UNARY_MINUS'))
            else:
                tokens.append(('OP', c))
            i += 1
            continue

        raise ValueError(f"Invalid character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    # 2. Recursive Descent Parsing
    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else None

        def consume(self, expected_type=None, expected_val=None):
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of expression")
            if expected_type and token[0] != expected_type:
                raise ValueError(f"Expected {expected_type}, got {token[0]}")
            if expected_val and token[1] != expected_val:
                raise ValueError(f"Expected {expected_val}, got {token[1]}")
            self.pos += 1
            return token

        def parse_expression(self):
            val = self.parse_term()
            while True:
                token = self.peek()
                if token and token[0] == 'OP' and token[1] in ('+', '-'):
                    op = token[1]
                    self.consume()
                    right = self.parse_term()
                    if op == '+':
                        val += right
                    else:
                        val -= right
                else:
                    break
            return val

        def parse_term(self):
            val = self.parse_factor()
            while True:
                token = self.peek()
                if token and token[0] == 'OP' and token[1] in ('*', '/'):
                    op = token[1]
                    self.consume()
                    right = self.parse_factor()
                    if op == '*':
                        val *= right
                    else:
                        if right == 0:
                            raise ZeroDivisionError("division by zero")
                        val /= right
                else:
                    break
            return val

        def parse_factor(self):
            token = self.peek()
            if token is None:
                raise ValueError("Unexpected end of expression")

            if token[0] == 'NUM':
                self.consume()
                return token[1]
            elif token[0] == 'OP' and token[1] == 'UNARY_MINUS':
                self.consume()
                return -self.parse_factor()
            elif token[0] == 'OP' and token[1] == '(':
                self.consume()
                val = self.parse_expression()
                self.consume('OP', ')')
                return val
            else:
                raise ValueError(f"Unexpected token: {token[1]}")

    parser = Parser(tokens)
    result = parser.parse_expression()
    if parser.peek():
        raise ValueError("Unexpected token at end of expression")
    return result
